//! Measures whether a synthetic document (generated by `synthpass-gen`)
//! survives the same Tier-1 pipeline real documents go through: OCR
//! (`synthpass-ocr`) followed by ICAO 9303 checksum validation (`mrz`).
//!
//! This is deliberately a real integration measurement, not a unit test of
//! the generator or the OCR engine in isolation — it exists to answer "does
//! the rendered image actually OCR back to a checksum-valid MRZ matching the
//! ground truth," the same question `crates/synthpass-ocr/examples/
//! mrz_corpus.rs` answers for the real `samples/` corpus, factored here into
//! a reusable library instead of example-local logic.

use image::DynamicImage;
use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};
use synthpass_gen::degrade::{apply_profile, CaptureProfile};
use synthpass_gen::{generate_from_seed, DocumentType, GeneratorConfig, Labels};
use synthpass_ocr::NativeOcr;

pub mod provider_bench;

/// Which capture profile to generate a corpus under. Shared between
/// `synthpass-bench`'s Tier-1 hit-rate CLI and `provider-bench`'s
/// multi-provider harness so both draw from the same corpus-generation code
/// path rather than two copies that could silently diverge.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProfileChoice {
    Clean,
    Mobile,
    Scanner,
    Worn,
    BorderKiosk,
    Damaged,
    All,
}

// Deliberately excludes `Damaged`: the other profiles degrade legibility,
// occlusion destroys data outright, and mixing it into `all` would move the
// hit-rate number every existing gate is calibrated against. Ask for it by
// name (`--profile damaged`) to measure recovery on its own.
const ROUND_ROBIN: [ProfileChoice; 5] = [
    ProfileChoice::Clean,
    ProfileChoice::Mobile,
    ProfileChoice::Scanner,
    ProfileChoice::Worn,
    ProfileChoice::BorderKiosk,
];

impl ProfileChoice {
    pub fn parse(s: &str) -> Result<Self, String> {
        match s.to_lowercase().as_str() {
            "clean" => Ok(Self::Clean),
            "mobile" => Ok(Self::Mobile),
            "scanner" => Ok(Self::Scanner),
            "worn" => Ok(Self::Worn),
            "border-kiosk" => Ok(Self::BorderKiosk),
            "damaged" => Ok(Self::Damaged),
            "all" => Ok(Self::All),
            other => Err(format!(
                "unknown profile '{other}' (valid: clean, mobile, scanner, worn, border-kiosk, damaged, all)"
            )),
        }
    }

    pub fn as_str(self) -> &'static str {
        match self {
            Self::Clean => "clean",
            Self::Mobile => "mobile",
            Self::Scanner => "scanner",
            Self::Worn => "worn",
            Self::BorderKiosk => "border-kiosk",
            Self::Damaged => "damaged",
            Self::All => "all",
        }
    }

    /// `None` for `Clean` (no degradation applied); `All` resolves to a
    /// concrete per-seed choice before this is ever called.
    pub fn capture_profile(self) -> Option<CaptureProfile> {
        match self {
            Self::Clean | Self::All => None,
            Self::Mobile => Some(CaptureProfile::Mobile),
            Self::Scanner => Some(CaptureProfile::Scanner),
            Self::Worn => Some(CaptureProfile::Worn),
            Self::BorderKiosk => Some(CaptureProfile::BorderKiosk),
            Self::Damaged => Some(CaptureProfile::Damaged),
        }
    }

    /// Resolves `All` to a concrete profile via round-robin over `seed_index`
    /// (the document's position in the corpus, not the raw seed value); every
    /// other variant is already concrete and passes through unchanged.
    pub fn resolve(self, seed_index: u64) -> Self {
        if self == Self::All {
            ROUND_ROBIN[(seed_index as usize) % ROUND_ROBIN.len()]
        } else {
            self
        }
    }
}

/// One generated document: its seed, the resolved (never `All`) profile it
/// was degraded under, the rendered image, and its ground-truth labels.
pub struct CorpusDoc {
    pub seed: u64,
    pub profile: ProfileChoice,
    pub image: DynamicImage,
    pub labels: Labels,
}

/// Generates `count` documents deterministically from seeds
/// `seed_start..seed_start + count`, applying `profile`'s degradation
/// (round-robining the five real profiles when `profile` is `All`), all
/// rendered as `document_type`'s ICAO 9303 MRZ format. The single
/// corpus-generation path shared by every bench binary in this crate.
pub fn generate_corpus(
    profile: ProfileChoice,
    seed_start: u64,
    count: u64,
    document_type: DocumentType,
) -> Vec<CorpusDoc> {
    (0..count)
        .map(|i| {
            let seed = seed_start + i;
            let resolved = profile.resolve(i);
            let config = GeneratorConfig::with_document_type(seed, document_type);
            let (image, labels, _passport) = generate_from_seed(&config);
            let image = match resolved.capture_profile() {
                Some(cp) => apply_profile(&image, cp, seed),
                None => image,
            };
            CorpusDoc {
                seed,
                profile: resolved,
                image,
                labels,
            }
        })
        .collect()
}

/// One real specimen loaded from `samples/`: its file stem, the decoded
/// image, and OPTIONAL ground truth read from a sibling
/// `samples/ocr_fixtures/<stem>.json` label file (the v1 `Extraction` shape
/// — verified against `samples/ocr_fixtures/Serbia_ID_Specimen_2008_back_with_mrz.json` before
/// writing this loader).
///
/// This exists because [`CorpusDoc`] cannot represent a real specimen:
/// `CorpusDoc::labels` is [`Labels`], which requires two 44-character MRZ
/// lines that only `synthpass-gen` can produce, since it is the one that
/// drew them. A photographed ID-card front has no MRZ to supply those lines
/// even when it has a hand-verified label file, so real-specimen ground
/// truth has to be a different, optional shape rather than a variant of
/// `Labels` — see `provider_bench`'s doc for how the two feed the same
/// accuracy loop despite the different shapes.
#[derive(Debug, Clone)]
pub struct RealSpecimenDoc {
    /// File stem (no extension, no directory) — the join key between the
    /// image and its optional `samples/ocr_fixtures/<name>.json` label, and
    /// the identity used in per-document report rows. Never a full path:
    /// `samples/` has already been reorganized once (see [`find_image_files`]'s
    /// doc), so nothing here should assume a subdirectory stays put.
    pub name: String,
    pub image: DynamicImage,
    /// `None` when `samples/ocr_fixtures/<name>.json` does not exist, or
    /// exists but fails to parse. Both cases mean "no ground truth for this
    /// specimen," not "load error" — most of `samples/` (every MRZ-less
    /// ID-card front, in particular) has no label file at all, by the
    /// nature of `samples/ocr_fixtures/` only covering the specimens someone
    /// has hand-verified. Treating a missing label as an error would make
    /// the loader fail exactly on the population Phase 1 exists to measure.
    pub labels: Option<synthpass_core::Extraction>,
    /// Which `samples/` document format this specimen represents, for
    /// `provider-bench --format`. See [`classify_specimen`] for how this is
    /// decided.
    pub class: SpecimenClass,
    /// Whether this specimen carries an MRZ at all, from
    /// [`MrzExpectations`] (`samples/corpus.jsonl`'s `mrz.present`, falling
    /// back to the `_no_mrz` filename tag).
    ///
    /// 42 of the corpus's specimens are ID-card fronts, border passes and
    /// driving-license faces that have no machine-readable zone anywhere on
    /// them. Reading no MRZ off one of those is the *correct* Tier-1 answer —
    /// this whole product refuses rather than guesses — but the bench walks
    /// the image directory and used to score every one of them as
    /// `no_mrz_found`, so 42 correct refusals were counted as failures and
    /// sat inside the headline hit rate's denominator. They are now scored
    /// out as [`MissReason::NoMrzExpected`], and a checksum-valid read off one
    /// of them is the genuine failure it always was
    /// ([`MissReason::FalsePositiveMrz`]).
    pub mrz_expected: bool,
}

/// Which `samples/` document format a specimen represents, for
/// `provider-bench --format`. Directory-based, not filename-based: `samples/`
/// has already been reorganized once (see [`find_image_files`]'s doc) and is
/// mid-reorg again as this is written, so anything reading the filename
/// itself would need re-deriving every time a specimen gets renamed or
/// re-fetched. The immediate parent directory is stable under a rename.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SpecimenClass {
    Passport,
    IdCard,
    DrivingLicense,
    /// `misc/`, or an `ocr_fixtures/`/`misc/` specimen whose label (if any)
    /// has no recognizable `document_type` — never guessed.
    Unclassified,
}

impl SpecimenClass {
    pub fn parse(s: &str) -> Result<Self, String> {
        match s.to_lowercase().as_str() {
            "passport" => Ok(Self::Passport),
            "id_card" => Ok(Self::IdCard),
            "driving_license" => Ok(Self::DrivingLicense),
            other => Err(format!(
                "unknown format '{other}' (valid: passport, id_card, driving_license; \
                 omit --format entirely to run everything)"
            )),
        }
    }

    pub fn as_str(self) -> &'static str {
        match self {
            Self::Passport => "passport",
            Self::IdCard => "id_card",
            Self::DrivingLicense => "driving_license",
            Self::Unclassified => "unclassified",
        }
    }
}

/// Classifies one specimen by its `samples/` subdirectory, falling back to
/// its ground-truth `document_type` (ICAO 9303 short code, or the odd
/// unnormalized long form seen in a couple of hand-written fixtures — e.g.
/// `PASSPORT` alongside `P`) for the two directories that mix formats
/// (`ocr_fixtures/`, which holds specimens hand-labelled from more than one
/// directory, and `misc/`).
///
/// The gap that used to be documented here — passport specimens misfiled under
/// `id_cards/`, which classified as `IdCard` and made `--format passport`
/// under-count — is closed: the corpus reorganisation moved them, and
/// `crates/synthpass-bench/tests/corpus_manifest.rs`'s
/// `the_directory_agrees_with_the_document_type_in_the_name` now fails if a
/// specimen is ever refiled into a directory that contradicts its own name.
/// Directory-first classification is therefore load-bearing on a checked
/// invariant rather than on the corpus happening to be tidy.
pub fn classify_specimen(
    image_path: &Path,
    labels: Option<&synthpass_core::Extraction>,
) -> SpecimenClass {
    match image_path
        .parent()
        .and_then(|p| p.file_name())
        .and_then(|n| n.to_str())
    {
        Some("passports") => return SpecimenClass::Passport,
        Some("id_cards") => return SpecimenClass::IdCard,
        Some("driving_licenses") => return SpecimenClass::DrivingLicense,
        _ => {}
    }
    match labels
        .and_then(|l| l.document_type.as_deref())
        .map(str::to_uppercase)
        .as_deref()
    {
        Some("P") | Some("PASSPORT") => SpecimenClass::Passport,
        Some("ID") | Some("I") | Some("ID1") | Some("ID2") | Some("ID3") => SpecimenClass::IdCard,
        _ => SpecimenClass::Unclassified,
    }
}

/// Image file extensions this loader will decode, matched case-insensitively.
/// Covers every format actually present under `samples/` (`jpg`/`jpeg`,
/// `png`, `webp`, `gif`) plus two more the `image` crate also decodes
/// (`bmp`, `tif`/`tiff`) in case a future specimen arrives in one of those.
const IMAGE_EXTENSIONS: &[&str] = &["jpg", "jpeg", "png", "webp", "gif", "bmp", "tif", "tiff"];

/// Recursively finds every image file under `dir`, returned in sorted order
/// for a deterministic corpus ordering (`std::fs::read_dir`'s own order is
/// OS- and filesystem-dependent, and this repo's engineering priorities put
/// deterministic behavior ahead of the convenience of skipping the sort).
///
/// Recursive rather than a fixed list of subdirectories — `samples/` has
/// already been reorganized once (continent/class subfolders) and stranded
/// two hardcoded references, which is exactly why
/// `crates/synthpass-ocr/examples/mrz_corpus.rs`'s `find_sample` searches
/// recursively too. A directory that can't be read (permissions, a dangling
/// symlink) is skipped rather than aborting the whole walk, for the same
/// "one bad entry costs one entry, not the run" reason `find_sample` returns
/// `Option` instead of panicking.
///
/// **Any path component containing `private` (case-insensitive) is skipped
/// unconditionally** — both a directory named `private` (the real local
/// convention: `samples/private/`) and a filename carrying the corpus
/// naming convention's `_Private_` token. These are real identity documents
/// a user has placed under `samples/` for their own local benchmarking,
/// gitignored (`.gitignore:63`: `samples/**/*Private*`) so they never reach
/// the repo — but this walk has no other signal to tell them apart from the
/// public specimen corpus, and the default real-specimen run must never
/// silently grow to include them (it did, once: 238 → 251 documents, with
/// no warning). Case-insensitive rather than matching the `.gitignore`
/// pattern's exact casing, because the directory itself is lowercase and a
/// single consistent rule is less to get wrong than two. `include_private`
/// is that explicit opt-in — `provider-bench --include-private` sets it, and
/// nothing else does; see [`load_real_specimens`].
fn find_image_files(dir: &Path, include_private: bool) -> Vec<PathBuf> {
    fn walk(dir: &Path, include_private: bool, out: &mut Vec<PathBuf>) {
        let Ok(entries) = std::fs::read_dir(dir) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if !include_private
                && path
                    .file_name()
                    .and_then(|n| n.to_str())
                    .is_some_and(|n| n.to_ascii_lowercase().contains("private"))
            {
                continue;
            }
            if path.is_dir() {
                walk(&path, include_private, out);
            } else if path
                .extension()
                .and_then(|e| e.to_str())
                .is_some_and(|e| IMAGE_EXTENSIONS.contains(&e.to_lowercase().as_str()))
            {
                out.push(path);
            }
        }
    }
    let mut out = Vec::new();
    walk(dir, include_private, &mut out);
    out.sort();
    out
}

/// Reads `samples_root/ocr_fixtures/<stem>.json` and parses it as a v1
/// [`synthpass_core::Extraction`]. Returns `None` — never an error — when
/// the file is absent, unreadable, or fails to parse: see
/// [`RealSpecimenDoc::labels`]'s doc for why "no ground truth" must never be
/// conflated with a loader failure.
///
/// A file that exists but fails to *parse* still returns `None`, but warns on
/// stderr first. Absent and malformed are both "unlabelled" to the caller,
/// and deliberately so — one broken file must not abort a corpus load — but
/// only one of them is normal, and a silent malformed label would shrink the
/// labelled population without anyone noticing.
/// The nested, versioned ground-truth schema `samples/private/<stem>.json`
/// uses (schema_version 1): per-field confidence, an MRZ check-digit
/// breakdown and a portrait box on top of the field values. The flat
/// `synthpass_core::Extraction` that `samples/ocr_fixtures/` files
/// deserialize into is a strict subset — [`PrivateSidecar::into_extraction`]
/// projects it. Only the fields the bench's accuracy loop actually reads are
/// modelled; `confidence`, `provenance` and `portrait` are deserialized past.
#[derive(serde::Deserialize)]
struct PrivateSidecar {
    #[serde(default)]
    fields: PrivateSidecarFields,
    #[serde(default)]
    mrz: Option<PrivateSidecarMrz>,
    #[serde(default)]
    extraction_method: String,
}

#[derive(serde::Deserialize, Default)]
struct PrivateSidecarFields {
    #[serde(default)]
    document_type: Option<String>,
    #[serde(default)]
    issuing_country: Option<String>,
    #[serde(default)]
    document_number: Option<String>,
    #[serde(default)]
    surname: Option<String>,
    #[serde(default)]
    given_names: Option<String>,
    #[serde(default)]
    nationality: Option<String>,
    #[serde(default)]
    date_of_birth: Option<String>,
    #[serde(default)]
    sex: Option<String>,
    #[serde(default)]
    date_of_expiry: Option<String>,
    #[serde(default)]
    personal_number: Option<String>,
}

#[derive(serde::Deserialize)]
struct PrivateSidecarMrz {
    #[serde(default)]
    lines: Option<String>,
    #[serde(default)]
    checks: Option<PrivateSidecarChecks>,
}

#[derive(serde::Deserialize)]
struct PrivateSidecarChecks {
    #[serde(default)]
    document_number: bool,
    #[serde(default)]
    date_of_birth: bool,
    #[serde(default)]
    date_of_expiry: bool,
    #[serde(default)]
    personal_number: bool,
    #[serde(default)]
    composite: bool,
}

impl PrivateSidecar {
    fn into_extraction(self) -> synthpass_core::Extraction {
        let mut e = synthpass_core::Extraction::default();
        let f = self.fields;
        e.document_type = f.document_type;
        e.issuing_country = f.issuing_country;
        e.document_number = f.document_number;
        e.surname = f.surname;
        e.given_names = f.given_names;
        e.nationality = f.nationality;
        e.date_of_birth = f.date_of_birth;
        e.sex = f.sex;
        e.date_of_expiry = f.date_of_expiry;
        e.personal_number = f.personal_number;
        if let Some(mrz) = self.mrz {
            e.mrz_line = mrz.lines;
            // Checksums are "valid" only if every ICAO check digit the
            // sidecar recorded passed — the same all-or-nothing predicate
            // `mrz::MrzData::valid()` applies, so a private specimen and a
            // generated one reach `provider_bench`'s classifier identically.
            e.mrz_checksums_valid = mrz.checks.map(|c| {
                c.document_number
                    && c.date_of_birth
                    && c.date_of_expiry
                    && c.personal_number
                    && c.composite
            });
        }
        e.extraction_method = self.extraction_method;
        e
    }
}

/// `samples/private/<stem>.json` -> [`synthpass_core::Extraction`], or `None`
/// when absent/malformed — same "one bad file costs one specimen, never the
/// run, but never silent on malformed" contract as [`load_ground_truth`],
/// which is this function's only caller.
fn load_private_ground_truth(
    samples_root: &Path,
    stem: &str,
) -> Option<synthpass_core::Extraction> {
    let path = samples_root.join("private").join(format!("{stem}.json"));
    let bytes = std::fs::read(&path).ok()?;
    match serde_json::from_slice::<PrivateSidecar>(&bytes) {
        Ok(sidecar) => Some(sidecar.into_extraction()),
        Err(e) => {
            eprintln!(
                "warning: {} exists but did not parse as a v1 PrivateSidecar ({e}) — \
                 treating this specimen as unlabelled",
                path.display()
            );
            None
        }
    }
}

pub fn load_ground_truth(samples_root: &Path, stem: &str) -> Option<synthpass_core::Extraction> {
    let path = samples_root
        .join("ocr_fixtures")
        .join(format!("{stem}.json"));
    let Ok(bytes) = std::fs::read(&path) else {
        // No flat `ocr_fixtures/` label. A `--include-private` specimen
        // carries its ground truth beside the image as `private/<stem>.json`
        // instead, in the richer nested schema `PrivateSidecar` models —
        // try that before giving up. Absent there too is the normal
        // unlabelled case and returns `None` silently.
        return load_private_ground_truth(samples_root, stem);
    };
    match serde_json::from_slice(&bytes) {
        Ok(extraction) => Some(extraction),
        Err(e) => {
            // A label file that exists but does not parse is a different
            // thing from no label file, and must not be silently folded into
            // it. Absent is the normal case (most of `samples/` has never
            // been hand-labelled); malformed means someone wrote a label and
            // it is broken, which would silently shrink the labelled
            // population this whole module exists to report honestly — the
            // exact failure mode `AccuracyStats`'s `Option` is there to
            // prevent, reintroduced one layer down. Still `None`, so one bad
            // file costs one specimen rather than the run, but never quiet.
            //
            // The path and the serde error are shape, not content: a
            // specimen filename and a parse position. Neither carries a
            // document field value, per CONTRIBUTING.md's PII rule.
            eprintln!(
                "warning: {} exists but did not parse as a v1 Extraction ({e}) — \
                 treating this specimen as unlabelled",
                path.display()
            );
            None
        }
    }
}

/// Whether each specimen stem is expected to carry an MRZ at all, read once
/// from `samples/corpus.jsonl` so a whole corpus load costs one file read.
///
/// Keyed by file stem rather than `(dir, filename)`: [`RealSpecimenDoc::name`]
/// is the stem, and it is the only identity a walked image and a manifest row
/// reliably share. Three stems appear twice in the manifest (the same document
/// stored in two formats — `…AZE_2013_mrz` as both `.jpg` and `.webp`, and two
/// more like it), and in every case both rows agree on `mrz.present`, so the
/// stem resolves unambiguously. [`MrzExpectations::load`] rejects the corpus
/// rather than guessing if that ever stops being true.
#[derive(Debug, Default, Clone)]
pub struct MrzExpectations {
    present: std::collections::HashMap<String, bool>,
}

impl MrzExpectations {
    /// Reads `samples_root/corpus.jsonl`. An absent or unreadable manifest
    /// yields an empty map rather than an error — every lookup then falls back
    /// to the filename tag, which is what [`Self::get`] does for an unlisted
    /// specimen anyway.
    pub fn load(samples_root: &Path) -> Self {
        let Ok(text) = std::fs::read_to_string(samples_root.join("corpus.jsonl")) else {
            return Self::default();
        };
        let mut present: std::collections::HashMap<String, bool> = std::collections::HashMap::new();
        for line in text.lines().filter(|l| !l.trim().is_empty()) {
            let Ok(row) = serde_json::from_str::<serde_json::Value>(line) else {
                continue;
            };
            let Some(filename) = row.get("filename").and_then(|v| v.as_str()) else {
                continue;
            };
            let Some(flag) = row
                .get("mrz")
                .and_then(|m| m.get("present"))
                .and_then(|v| v.as_bool())
            else {
                continue;
            };
            let stem = filename.rsplit_once('.').map_or(filename, |(s, _)| s);
            if let Some(prev) = present.insert(stem.to_string(), flag) {
                // Two rows sharing a stem must agree, or the stem is not a
                // usable key and a specimen would silently take whichever row
                // happened to be read last.
                assert_eq!(
                    prev, flag,
                    "corpus.jsonl: stem {stem:?} appears twice with disagreeing mrz.present"
                );
            }
        }
        Self { present }
    }

    /// Whether `stem` is expected to carry an MRZ.
    ///
    /// Manifest first, filename tag as the fallback. The tag alone is not
    /// enough: two driving-license fronts
    /// (`Bosnia_Herzegovina_Driving_License_Specimen_face`/`_front`) predate the
    /// `_mrz`/`_no_mrz` naming convention and carry no tag, while the manifest
    /// records them correctly. The fallback still matters in the other
    /// direction — an image can be on disk with no manifest row at all
    /// (`Kenya_Passport_Specimen_P0_KEN_XXXX_no_mrz.jpg` is, as this is
    /// written), and defaulting such a specimen to "expected" would score a
    /// correct refusal as a detection failure, which is the whole bug this type
    /// exists to fix.
    pub fn get(&self, stem: &str) -> bool {
        self.present
            .get(stem)
            .copied()
            .unwrap_or_else(|| !stem.to_ascii_lowercase().contains("no_mrz"))
    }
}

/// Loads one real specimen from `image_path`, attaching ground truth from
/// `samples_root/ocr_fixtures/<stem>.json` when one exists and its MRZ
/// expectation from `expectations`.
///
/// Returns `None` when `image_path` doesn't exist, isn't readable, or isn't
/// a format the `image` crate can decode — the same "skip, don't abort"
/// contract as [`find_image_files`]. A caller checking a hand-picked path
/// (rather than one this crate's own walk produced) gets the same graceful
/// handling, which is what makes "loader given a nonexistent file" a safe,
/// panic-free case to test.
pub fn load_specimen(
    samples_root: &Path,
    image_path: &Path,
    expectations: &MrzExpectations,
) -> Option<RealSpecimenDoc> {
    let name = image_path.file_stem()?.to_str()?.to_string();
    // Content-sniffing, not extension-trusting: `image::open` picks its decoder
    // from the file name, so a JPEG called `.png` returns `None` here and the
    // specimen vanishes from the benchmark without a word. Three corpus files
    // were in exactly that state.
    let image = synthpass_ocr::decode_image(image_path).ok()?;
    let labels = load_ground_truth(samples_root, &name);
    let class = classify_specimen(image_path, labels.as_ref());
    let mrz_expected = expectations.get(&name);
    Some(RealSpecimenDoc {
        name,
        image,
        labels,
        class,
        mrz_expected,
    })
}

/// Loads every image file found recursively under `samples_root` as a
/// [`RealSpecimenDoc`], attaching ground truth from `samples_root/
/// ocr_fixtures/<stem>.json` wherever that file exists.
///
/// Callers pass `repo_root().join("samples")` — the same directory every
/// other real-corpus harness in this workspace reads from
/// (`crates/synthpass-ocr/examples/mrz_corpus.rs`). `samples/ocr_fixtures/`
/// itself holds specimen images too (the ones someone has hand-labelled),
/// and those are included in the walk like any other image under
/// `samples_root` — there is no separate code path for them, and no
/// specimen appears twice (`samples/ocr_fixtures/`'s images are not
/// duplicated anywhere else in the tree).
pub fn load_real_specimens(samples_root: &Path, include_private: bool) -> Vec<RealSpecimenDoc> {
    let expectations = MrzExpectations::load(samples_root);
    find_image_files(samples_root, include_private)
        .into_iter()
        .filter_map(|path| load_specimen(samples_root, &path, &expectations))
        .collect()
}

/// Why a document missed. An enum rather than the free-text string this
/// used to be, so misses **aggregate** — "37 of 50 missed" is not actionable
/// until you know whether they are 37 checksum failures or 37 documents
/// where OCR found no MRZ at all, and prose has to be read one line at a
/// time to find out.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum MissReason {
    /// The OCR stage itself failed (bad image, engine error).
    OcrError(String),
    /// OCR produced text, but nothing MRZ-shaped could be parsed out of it.
    NoMrzFound(String),
    /// An MRZ parsed, but its ICAO 9303 check digits did not validate.
    /// `failing` names which ones, via [`mrz::Checks::failed`] — e.g.
    /// `["composite"]` or `["document_number", "composite"]` — so
    /// `checksum_failed` (the largest real-specimen miss bucket measured so
    /// far, see `knowledge/MRZ_SEQUENCE_COMPLETENESS.md` chunk 1) stops being
    /// one undifferentiated count.
    ///
    /// `specimen_nonconforming` is set only for a real specimen that carries a
    /// hand-transcribed `mrz_line` label whose printed zone the run's OCR
    /// recovered faithfully: the check digits fail because the *printed*
    /// document is non-conforming (a `TEMPLATE` / `ÖRNEK` / all-zeros zone),
    /// not because OCR misread it. It stays `false` for every unlabelled
    /// document and for a labelled one whose recovered zone differs from the
    /// transcription — see the 2026-09-08 checksum_failed writeup. `miss_kind`
    /// reports the two as `checksum_failed_specimen` vs `checksum_failed`.
    ChecksumFailed {
        failing: Vec<&'static str>,
        specimen_nonconforming: bool,
    },
    /// A checksum-valid MRZ that disagrees with the ground truth. Rare and
    /// interesting: the check digits can validate over a misread that
    /// happens to stay self-consistent.
    DocumentNumberMismatch { got: String, expected: String },
    /// The specimen's own MRZ zone is redacted in the image — blacked out,
    /// X-ed over, or scrambled by whoever published the specimen. Whatever
    /// OCR read there is an artefact of the redaction bar, not a misread of a
    /// real zone, so this is neither an OCR-accuracy signal nor something a
    /// better parser could recover. Real specimens only (derived from the
    /// `*_redacted_mrz` filename tag); the synthetic corpus never produces it.
    /// `provider-bench` reports these as `redacted_mrz` and excludes them from
    /// the Tier-1 hit-rate denominator — see the 2026-09-08 `checksum_failed`
    /// writeup, population B.
    Redacted,
    /// The specimen carries no MRZ at all — an ID-card front, a border pass, a
    /// driving-license face ([`RealSpecimenDoc::mrz_expected`] is false) — and
    /// the run correctly read none. **This is a success, not a miss.** It is a
    /// `MissReason` only because that is how this harness spells "produced no
    /// Tier-1 record", and it is scored off the hit-rate denominator exactly
    /// like [`Self::Redacted`]: a document with nothing to find can neither
    /// prove nor disprove detection accuracy.
    ///
    /// Reported as `no_mrz_expected`. Its count moving means the corpus
    /// changed, not that anything regressed, so it stays out of
    /// `provider-bench`'s regression buckets.
    NoMrzExpected,
    /// The specimen carries no MRZ, and the run returned a **checksum-valid
    /// one anyway**. A hallucinated document.
    ///
    /// This is the most serious outcome the bench can report and it had no
    /// representation at all until now: such a document has no
    /// `ocr_fixtures/` label to contradict (MRZ-less fronts are exactly the
    /// population that goes unlabelled), so it fell through every gate and was
    /// counted as a **Tier-1 hit**. `Monaco_ID_Specimen_XXXX_front_no_mrz.png`
    /// really did produce one; it turned out to be a mislabelled file rather
    /// than a hallucination, and the fix then was to correct the label —
    /// which only works if the harness says something when it happens.
    ///
    /// Reported as `false_positive_mrz`, inside the denominator, and a
    /// regression bucket: growth here must fail the gate.
    FalsePositiveMrz,
}

impl std::fmt::Display for MissReason {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::OcrError(e) => write!(f, "OCR error: {e}"),
            Self::NoMrzFound(e) => write!(f, "no MRZ found: {e}"),
            Self::ChecksumFailed {
                failing,
                specimen_nonconforming,
            } => {
                write!(f, "checksum invalid: {}", failing.join(", "))?;
                if *specimen_nonconforming {
                    write!(f, " (printed zone is non-conforming, read faithfully)")?;
                }
                Ok(())
            }
            Self::DocumentNumberMismatch { got, expected } => {
                write!(
                    f,
                    "document number mismatch: got {got:?}, expected {expected:?}"
                )
            }
            Self::Redacted => write!(f, "MRZ redacted in the specimen"),
            Self::NoMrzExpected => {
                write!(f, "no MRZ on this document, and none was read (correct)")
            }
            Self::FalsePositiveMrz => write!(
                f,
                "FALSE POSITIVE: checksum-valid MRZ read off a document that carries none"
            ),
        }
    }
}

/// Stable, machine-readable name for a miss class — shared by both bench
/// binaries (`synthpass-bench`'s synthetic-corpus reporting and
/// `provider-bench`'s real-specimen reporting) so "checksum_failed" means the
/// same string in both, rather than two hand-written copies that could drift.
pub fn miss_kind(reason: &MissReason) -> &'static str {
    match reason {
        MissReason::OcrError(_) => "ocr_error",
        MissReason::NoMrzFound(_) => "no_mrz_found",
        MissReason::ChecksumFailed {
            specimen_nonconforming: true,
            ..
        } => "checksum_failed_specimen",
        MissReason::ChecksumFailed { .. } => "checksum_failed",
        MissReason::DocumentNumberMismatch { .. } => "document_number_mismatch",
        MissReason::Redacted => "redacted_mrz",
        MissReason::NoMrzExpected => "no_mrz_expected",
        MissReason::FalsePositiveMrz => "false_positive_mrz",
    }
}

/// Per-field read quality for one document.
///
/// The point of this type: a binary hit tells you *that* a document failed,
/// never *where*. A 55% hit rate is consistent with one systematically
/// broken field and with uniform per-character noise, and those call for
/// completely different fixes. CER localises it.
#[derive(Debug, Clone)]
pub struct FieldOutcome {
    /// Field name, matching `mrz::MrzData`'s own field names.
    pub field: &'static str,
    /// Ground truth, from the generator's labels.
    pub expected: String,
    /// What OCR + parse actually read. `None` when no MRZ parsed at all.
    pub got: Option<String>,
    /// Character error rate: Levenshtein distance / `expected.len()`, so
    /// `0.0` is a perfect read and `1.0` is a total loss. Not clamped above
    /// `1.0` — an insertion-heavy misread genuinely can exceed it, and
    /// hiding that would flatter the number.
    pub cer: f64,
}

/// Outcome of running one generated document through OCR + checksum
/// validation.
#[derive(Debug, Clone)]
pub struct HitResult {
    /// `true` iff OCR recovered a checksum-valid MRZ whose document number
    /// matches the generator's ground truth. **Deliberately unchanged** by
    /// the addition of per-field reporting below — the M4 CI gate is defined
    /// on this number, so it has to keep meaning exactly what it meant when
    /// the 55% baseline and the 30% floor were measured.
    pub hit: bool,
    /// Why it missed. `None` on a hit.
    pub reason: Option<MissReason>,
    /// Wall-clock time spent in this check (OCR + parse), for reporting.
    pub elapsed: Duration,
    /// Per-field read quality — populated whenever an MRZ parsed at all,
    /// **including when its checksum failed**, since a checksum-invalid
    /// parse is exactly the case where knowing which field broke is most
    /// useful. Empty only when there was nothing to compare.
    pub fields: Vec<FieldOutcome>,
    /// Line-1 integrity verdict (`synthpass_core::fusion`) on the *read*
    /// MRZ, whenever one parsed — independent of `hit`. The headline number
    /// this exists for: among documents where `hit` is `true` (the Tier-1
    /// gate a checksum alone can prove), what fraction still get flagged
    /// here, since the checksum never covered `document_type`,
    /// `issuing_country`, `surname`, or `given_names` in the first place.
    pub line1_integrity: Option<synthpass_core::fusion::Verdict>,
    /// The raw OCR text `mrz::find_and_parse` was handed, whenever OCR
    /// itself succeeded (`None` only on `MissReason::OcrError`, where there
    /// is no text to show). Threaded through unconditionally rather than
    /// gated behind a flag: it costs nothing extra (the OCR pass already ran
    /// inside `check_document`), and `synthpass-bench --dump-ocr` is the
    /// only consumer that prints it — see that flag's doc comment for why
    /// this exists (the M6 TD1 root-cause diagnosis: nothing could show what
    /// OCR actually returned before the MRZ scanner ate it).
    pub raw_text: Option<String>,
}

/// Runs `image` through `ocr` and checks the result against `expected`'s
/// ground-truth MRZ. Writes `image` to a temporary file first — neither
/// `NativeOcr::recognize` nor the pipeline's `OcrEngine` trait expose an
/// in-memory entry point today, so a temp file is the same pattern every
/// other OCR call site in this workspace already uses.
pub fn check_document(ocr: &NativeOcr, image: &DynamicImage, expected: &Labels) -> HitResult {
    let start = Instant::now();

    let path = std::env::temp_dir().join(format!(
        "synthpass-bench-{}-{}.png",
        std::process::id(),
        fastrand_seed()
    ));
    let write_result = image.save(&path);
    let (reason, fields, line1_integrity, raw_text) = run_check(&path, write_result, ocr, expected);
    let _ = std::fs::remove_file(&path);

    HitResult {
        hit: reason.is_none(),
        reason,
        elapsed: start.elapsed(),
        fields,
        line1_integrity,
        raw_text,
    }
}

/// Returns the miss reason (`None` on a hit), the per-field breakdown, and
/// the line-1 integrity verdict.
///
/// Structured so the breakdown survives a miss: the old version returned
/// early on a checksum failure, which threw away the read it had just
/// obtained — precisely the read that says *which field* broke the checksum.
type CheckOutcome = (
    Option<MissReason>,
    Vec<FieldOutcome>,
    Option<synthpass_core::fusion::Verdict>,
    Option<String>,
);

/// Parses `expected.mrz_lines` back through the [`mrz`] parser that matches
/// `expected.mrz_format` — [`mrz::parse_td1`]/[`mrz::parse_td2`]/
/// [`mrz::parse_td3`], reused directly rather than re-derived from line count
/// (the labels already carry the format Phase 1 added, so there is no need
/// to guess it back from the lines themselves the way
/// `MrzFormat::guess_from_lines` does for data that never recorded it).
///
/// `pub(crate)`: also used by [`provider_bench::prep_corpus`], which has the
/// same "ground truth for the synthetic corpus" job for the M7 multi-provider
/// harness — one parse-dispatch implementation, not two that could drift.
pub(crate) fn parse_ground_truth_mrz(expected: &Labels) -> Result<mrz::MrzData, mrz::MrzError> {
    match expected.mrz_format {
        DocumentType::TD1 => mrz::parse_td1(
            &expected.mrz_lines[0],
            &expected.mrz_lines[1],
            &expected.mrz_lines[2],
        ),
        DocumentType::TD2 => mrz::parse_td2(&expected.mrz_lines[0], &expected.mrz_lines[1]),
        DocumentType::TD3 => mrz::parse_td3(&expected.mrz_lines[0], &expected.mrz_lines[1]),
        DocumentType::MrvA => mrz::parse_mrv_a(&expected.mrz_lines[0], &expected.mrz_lines[1]),
        DocumentType::MrvB => mrz::parse_mrv_b(&expected.mrz_lines[0], &expected.mrz_lines[1]),
    }
}

fn run_check(
    path: &std::path::Path,
    write_result: image::ImageResult<()>,
    ocr: &NativeOcr,
    expected: &Labels,
) -> CheckOutcome {
    if let Err(e) = write_result {
        return (
            Some(MissReason::OcrError(format!(
                "failed to write temp image: {e}"
            ))),
            Vec::new(),
            None,
            None,
        );
    }

    let text = match ocr.recognize(path) {
        Ok(text) => text,
        Err(e) => return (Some(MissReason::OcrError(e)), Vec::new(), None, None),
    };

    // Ground truth is the generator's own MRZ lines parsed back through the
    // matching per-format parser (see `parse_ground_truth_mrz`). Comparing
    // `MrzData` to `MrzData` keeps both sides in identical formats — dates
    // already century-expanded to ISO, names already split — so the CER
    // measures the *read*, not a formatting difference between the visual
    // zone and the machine-readable one. The labels are correct by
    // construction (M2's DoD), so this parse cannot legitimately fail.
    let truth = match parse_ground_truth_mrz(expected) {
        Ok(truth) => truth,
        Err(e) => {
            return (
                Some(MissReason::OcrError(format!(
                    "ground-truth MRZ failed to parse — this is a generator bug, not a read \
                     failure: {e:?}"
                ))),
                Vec::new(),
                None,
                Some(text),
            )
        }
    };

    let decoded = match mrz::find_and_parse(&text) {
        Ok(decoded) => decoded,
        Err(e) => {
            return (
                Some(MissReason::NoMrzFound(format!("{e:?}"))),
                total_loss(&truth),
                None,
                Some(text),
            )
        }
    };

    let fields = compare_fields(&truth, &decoded);
    let line1_integrity = Some(synthpass_core::fusion::check_line1_integrity(&decoded));

    if !decoded.valid() {
        return (
            Some(MissReason::ChecksumFailed {
                failing: decoded.checks.failed().iter().map(|f| f.as_str()).collect(),
                // Synthetic corpus: every document is generated from a
                // conformant zone, so a checksum failure here is always the
                // OCR/parse pipeline, never a non-conforming source.
                specimen_nonconforming: false,
            }),
            fields,
            line1_integrity,
            Some(text),
        );
    }
    if decoded.document_number != truth.document_number {
        return (
            Some(MissReason::DocumentNumberMismatch {
                got: decoded.document_number.clone(),
                expected: truth.document_number.clone(),
            }),
            fields,
            line1_integrity,
            Some(text),
        );
    }
    (None, fields, line1_integrity, Some(text))
}

/// The fields compared per document, as `(name, accessor)` pairs. One list so
/// `compare_fields` and `total_loss` cannot drift apart.
type FieldAccessor = fn(&mrz::MrzData) -> String;

const COMPARED_FIELDS: [(&str, FieldAccessor); 10] = [
    ("document_type", |m| m.document_type.clone()),
    ("issuing_country", |m| m.issuing_country.clone()),
    ("document_number", |m| m.document_number.clone()),
    ("surname", |m| m.surname.clone()),
    ("given_names", |m| m.given_names.clone()),
    ("nationality", |m| m.nationality.clone()),
    ("date_of_birth", |m| m.date_of_birth.clone()),
    ("sex", |m| m.sex.clone()),
    ("date_of_expiry", |m| m.date_of_expiry.clone()),
    ("personal_number", |m| {
        m.personal_number.clone().unwrap_or_default()
    }),
];

fn compare_fields(truth: &mrz::MrzData, got: &mrz::MrzData) -> Vec<FieldOutcome> {
    let mut out: Vec<FieldOutcome> = COMPARED_FIELDS
        .iter()
        .map(|(field, get)| {
            let expected = get(truth);
            let actual = get(got);
            FieldOutcome {
                field,
                cer: cer(&expected, &actual),
                expected,
                got: Some(actual),
            }
        })
        .collect();

    // The raw MRZ characters themselves — the most diagnostic single number
    // here, since every parsed field above is a substring of these 88
    // characters and a per-field rate cannot distinguish "read one field
    // badly" from "read the whole zone slightly badly".
    out.push(FieldOutcome {
        field: "mrz_lines",
        cer: cer(&truth.mrz_lines, &got.mrz_lines),
        expected: truth.mrz_lines.clone(),
        got: Some(got.mrz_lines.clone()),
    });
    out
}

/// The breakdown for a document whose MRZ was never found: every field is a
/// total loss. Recorded explicitly rather than as an empty vector so these
/// documents still count in a mean CER instead of silently improving it.
fn total_loss(truth: &mrz::MrzData) -> Vec<FieldOutcome> {
    COMPARED_FIELDS
        .iter()
        .map(|(field, get)| FieldOutcome {
            field,
            expected: get(truth),
            got: None,
            cer: 1.0,
        })
        .chain(std::iter::once(FieldOutcome {
            field: "mrz_lines",
            expected: truth.mrz_lines.clone(),
            got: None,
            cer: 1.0,
        }))
        .collect()
}

/// Character error rate: Levenshtein distance from `expected` to `got`,
/// divided by `expected`'s length.
///
/// Two empty strings score `0.0` (a correctly-read absent optional field is
/// a perfect read, not a failure); a non-empty read against an empty
/// expectation scores `1.0`, since there is no length to divide by but the
/// read is certainly wrong.
pub fn cer(expected: &str, got: &str) -> f64 {
    let expected: Vec<char> = expected.chars().collect();
    let got: Vec<char> = got.chars().collect();
    if expected.is_empty() {
        return if got.is_empty() { 0.0 } else { 1.0 };
    }
    levenshtein(&expected, &got) as f64 / expected.len() as f64
}

/// Levenshtein edit distance over two char slices.
///
/// Two rolling rows rather than a full `m*n` matrix — the distance is all
/// that is wanted, never the alignment. Deliberately hand-written: adding
/// the `strsim` crate for one textbook function would spend a dependency
/// (see `knowledge/VISION.md` §1 on new dependencies) on ~20 lines of `std`.
fn levenshtein(a: &[char], b: &[char]) -> usize {
    if a.is_empty() {
        return b.len();
    }
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for (i, &ca) in a.iter().enumerate() {
        cur[0] = i + 1;
        for (j, &cb) in b.iter().enumerate() {
            let substitution = prev[j] + usize::from(ca != cb);
            let deletion = prev[j + 1] + 1;
            let insertion = cur[j] + 1;
            cur[j + 1] = substitution.min(deletion).min(insertion);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

/// A cheap, non-cryptographic per-call disambiguator for temp file names —
/// avoids collisions when `check_document` is called many times in the same
/// process within the same millisecond (the process ID alone isn't enough).
fn fastrand_seed() -> u64 {
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    COUNTER.fetch_add(1, Ordering::Relaxed)
}

#[cfg(test)]
mod tests {
    use super::*;
    use synthpass_gen::{generate_from_seed, GeneratorConfig};

    /// Hand-computed edit distances. These are the textbook cases; if this
    /// ever fails, the rolling-row indexing is wrong, and every CER number
    /// in every benchmark report is wrong with it.
    #[test]
    fn levenshtein_matches_hand_computed_distances() {
        let d = |a: &str, b: &str| {
            let a: Vec<char> = a.chars().collect();
            let b: Vec<char> = b.chars().collect();
            levenshtein(&a, &b)
        };
        assert_eq!(d("", ""), 0);
        assert_eq!(d("", "abc"), 3, "pure insertion");
        assert_eq!(d("abc", ""), 3, "pure deletion");
        assert_eq!(d("abc", "abc"), 0);
        assert_eq!(d("kitten", "sitting"), 3, "the canonical example");
        assert_eq!(d("flaw", "lawn"), 2);
        // The confusions this instrument exists to count: one substitution.
        assert_eq!(d("L898902C3", "L898902C8"), 1);
        // Six of the ten characters are zeros read as the letter O.
        assert_eq!(d("0070070071", "OO7OO7OO71"), 6, "O/0 across the field");
    }

    #[test]
    fn cer_normalizes_by_expected_length() {
        assert_eq!(cer("ABCDE", "ABCDE"), 0.0, "perfect read");
        assert_eq!(cer("ABCDE", "ABCDX"), 0.2, "one of five wrong");
        assert_eq!(cer("AB", ""), 1.0, "nothing read is a total loss");
        assert_eq!(cer("", ""), 0.0, "correctly-read absent field is perfect");
        assert_eq!(cer("", "X"), 1.0, "read something where nothing was");
        assert!(
            cer("AB", "XXXXXX") > 1.0,
            "an insertion-heavy misread is allowed to exceed 1.0 rather than \
             being clamped into looking better than it is"
        );
    }

    /// A checksum failure must still produce a breakdown — that is the whole
    /// point of restructuring `run_check` around it. Uses the generator's own
    /// ground truth, corrupted in one field, so no OCR run is needed.
    #[test]
    fn a_checksum_invalid_read_still_reports_per_field_detail() {
        let config = GeneratorConfig::new(7);
        let (_image, labels, _passport) = generate_from_seed(&config);
        let truth =
            mrz::parse_td3(&labels.mrz_lines[0], &labels.mrz_lines[1]).expect("labels parse");

        let mut misread = truth.clone();
        misread.surname = format!("{}X", truth.surname);

        let fields = compare_fields(&truth, &misread);
        assert_eq!(
            fields.len(),
            COMPARED_FIELDS.len() + 1,
            "every field plus the raw MRZ lines"
        );

        let surname = fields.iter().find(|f| f.field == "surname").unwrap();
        assert!(surname.cer > 0.0, "the corrupted field must show error");
        for f in fields.iter().filter(|f| f.field != "surname") {
            assert_eq!(f.cer, 0.0, "{} should be a clean read", f.field);
        }
    }

    /// `MissReason::ChecksumFailed`'s `failing` payload, `miss_kind`, and
    /// `Display` — the diagnostic chunk 1 of
    /// `knowledge/MRZ_SEQUENCE_COMPLETENESS.md` adds. No OCR needed: an ICAO
    /// specimen with one date tampered (same fixture shape `crates/mrz`'s own
    /// tests use) fails exactly `date_of_birth` and `composite`, since the
    /// composite range covers the date-of-birth field.
    #[test]
    fn checksum_failed_names_the_failing_fields() {
        let l1 = "P<UTOERIKSSON<<ANNA<MARIA<<<<<<<<<<<<<<<<<<<";
        let l2 = "L898902C36UTO7408122F1204159ZE184226B<<<<<10";
        let tampered = l2.replacen("740812", "750812", 1);
        let decoded = mrz::parse_td3(l1, &tampered).expect("shape is still valid TD3");
        assert!(!decoded.valid());

        let failing: Vec<&'static str> =
            decoded.checks.failed().iter().map(|f| f.as_str()).collect();
        assert_eq!(failing, vec!["date_of_birth", "composite"]);

        let reason = MissReason::ChecksumFailed {
            failing: failing.clone(),
            specimen_nonconforming: false,
        };
        assert_eq!(miss_kind(&reason), "checksum_failed");
        assert_eq!(
            reason.to_string(),
            "checksum invalid: date_of_birth, composite"
        );

        let specimen = MissReason::ChecksumFailed {
            failing,
            specimen_nonconforming: true,
        };
        assert_eq!(miss_kind(&specimen), "checksum_failed_specimen");
    }

    /// A document whose MRZ never parsed must count as a total loss in every
    /// field rather than vanishing from the aggregate — otherwise the worst
    /// documents would silently improve the mean CER.
    #[test]
    fn an_unparsed_document_is_a_total_loss_not_an_absence() {
        let config = GeneratorConfig::new(11);
        let (_image, labels, _passport) = generate_from_seed(&config);
        let truth =
            mrz::parse_td3(&labels.mrz_lines[0], &labels.mrz_lines[1]).expect("labels parse");

        let fields = total_loss(&truth);
        assert_eq!(fields.len(), COMPARED_FIELDS.len() + 1);
        assert!(fields.iter().all(|f| f.cer == 1.0));
        assert!(fields.iter().all(|f| f.got.is_none()));
    }

    /// Needs the real `.rten` OCR models at the repo root — same requirement
    /// as `crates/synthpass-ocr/tests/native_ocr_e2e.rs`, run with
    /// `cargo test -p synthpass-bench -- --ignored`.
    ///
    /// Checks a handful of seeds and requires at least one hit rather than
    /// asserting a specific seed or rate: this proves the OCR + checksum
    /// wiring actually works end to end, without duplicating the aggregate
    /// hit-rate measurement that `synthpass-bench`'s corpus runner binary
    /// owns (real-world hit rate on generated documents is well under 100%,
    /// see the M4 benchmark report).
    #[test]
    #[ignore]
    fn some_clean_generated_documents_hit() {
        let root = repo_root();
        let ocr = NativeOcr::load(
            &root.join("text-detection.rten"),
            &root.join("text-recognition.rten"),
        )
        .expect("failed to load OCR models — run from the repo root");

        let mut results = Vec::new();
        for seed in 0..5 {
            let config = GeneratorConfig::new(seed);
            let (image, labels, _passport) = generate_from_seed(&config);
            results.push(check_document(&ocr, &image, &labels));
        }

        assert!(
            results.iter().any(|r| r.hit),
            "expected at least one hit across 5 seeds, got: {:?}",
            results.iter().map(|r| &r.reason).collect::<Vec<_>>()
        );
    }

    /// Ground truth loads and parses correctly when a `samples/ocr_fixtures/
    /// <stem>.json` label file exists. `Serbia_ID_Specimen_2008_back_with_mrz`
    /// is the specimen the task brief pointed at to confirm the v1
    /// `Extraction` shape before any code was written, so it doubles as the
    /// loader's own confirmation.
    #[test]
    fn specimen_loader_finds_labels_when_present() {
        let root = repo_root();
        let samples = root.join("samples");
        let truth = load_ground_truth(&samples, "Serbia_ID_Specimen_2008_back_with_mrz")
            .expect("samples/ocr_fixtures/Serbia_ID_Specimen_2008_back_with_mrz.json should parse");
        assert_eq!(truth.document_number.as_deref(), Some("955555546"));
        assert_eq!(truth.surname.as_deref(), Some("TEST"));
        assert_eq!(truth.given_names.as_deref(), Some("MILICA"));
    }

    /// Directory alone decides `passports/`, `id_cards/`, and
    /// `driving_licenses/` — no label needed, and a label that disagrees
    /// (which should never happen, but the classifier must not be fooled by
    /// hypothetically-bad label data) still loses to the directory.
    #[test]
    fn classify_specimen_uses_directory_first() {
        let disagreeing_label = extraction_with_document_type("ID");
        assert_eq!(
            classify_specimen(Path::new("samples/passports/Foo.jpg"), None),
            SpecimenClass::Passport
        );
        assert_eq!(
            classify_specimen(
                Path::new("samples/passports/Foo.jpg"),
                Some(&disagreeing_label)
            ),
            SpecimenClass::Passport,
            "directory wins over a disagreeing label"
        );
        assert_eq!(
            classify_specimen(Path::new("samples/id_cards/Foo.jpg"), None),
            SpecimenClass::IdCard
        );
        assert_eq!(
            classify_specimen(Path::new("samples/driving_licenses/Foo.jpg"), None),
            SpecimenClass::DrivingLicense
        );
    }

    /// `ocr_fixtures/` and `misc/` mix formats, so classification falls back
    /// to the specimen's own labelled `document_type` — both the ICAO short
    /// code (`P`, `ID`, `I`) and the unnormalized long form seen in one real
    /// fixture (`PASSPORT`, see `Cetis_Sample_Passport_Specimen_2022_inner_page_mrz.json`).
    #[test]
    fn classify_specimen_falls_back_to_label_for_mixed_directories() {
        let passport_short = extraction_with_document_type("P");
        let passport_long = extraction_with_document_type("PASSPORT");
        let id_short = extraction_with_document_type("ID");
        for path in ["samples/ocr_fixtures/Foo.jpg", "samples/misc/Foo.jpg"] {
            assert_eq!(
                classify_specimen(Path::new(path), Some(&passport_short)),
                SpecimenClass::Passport,
                "{path} with document_type P"
            );
            assert_eq!(
                classify_specimen(Path::new(path), Some(&passport_long)),
                SpecimenClass::Passport,
                "{path} with document_type PASSPORT"
            );
            assert_eq!(
                classify_specimen(Path::new(path), Some(&id_short)),
                SpecimenClass::IdCard,
                "{path} with document_type ID"
            );
        }
    }

    /// No label at all, or a label with no `document_type`/an unrecognized
    /// one, is `Unclassified` rather than a guess — this classifier must
    /// never fabricate a class it has no evidence for.
    #[test]
    fn classify_specimen_is_unclassified_without_directory_or_recognizable_label() {
        assert_eq!(
            classify_specimen(Path::new("samples/ocr_fixtures/Foo.jpg"), None),
            SpecimenClass::Unclassified
        );
        let visa = extraction_with_document_type("V");
        assert_eq!(
            classify_specimen(Path::new("samples/misc/Foo.jpg"), Some(&visa)),
            SpecimenClass::Unclassified,
            "a visa is neither a passport nor an ID card"
        );
    }

    /// `Extraction` has a custom `Drop` (`ZeroizeOnDrop`), so struct-update
    /// syntax (`..Default::default()`) against a temporary doesn't
    /// typecheck — build it field-by-field instead.
    fn extraction_with_document_type(document_type: &str) -> synthpass_core::Extraction {
        let mut e = synthpass_core::Extraction::default();
        e.document_type = Some(document_type.to_string());
        e
    }

    /// A specimen with an image but no matching `samples/ocr_fixtures/
    /// <stem>.json` reports `labels: None` — not an error, not a panic. This
    /// is the common case in `samples/`: every MRZ-less ID-card front has no
    /// label file at all, and the loader has to treat that as "unlabelled,"
    /// per this crate's whole reason for existing (see `RealSpecimenDoc`'s
    /// doc). `Bulgaria_ID_Specimen_2024_front_no_mrz.png` has no sibling JSON under
    /// `samples/ocr_fixtures/` as of this writing.
    /// A label file that exists but is malformed reads as unlabelled rather
    /// than aborting the load — but is not silently identical to "no label
    /// file", which is what the warning in [`load_ground_truth`] is for.
    /// Written to a temp `ocr_fixtures/` tree rather than `samples/`, so the
    /// real corpus never has to carry a deliberately-broken fixture.
    #[test]
    fn a_malformed_label_file_reads_as_unlabelled_without_aborting() {
        let root = std::env::temp_dir().join(format!(
            "synthpass-bench-malformed-label-{}-{}",
            std::process::id(),
            fastrand_seed()
        ));
        let fixtures = root.join("ocr_fixtures");
        std::fs::create_dir_all(&fixtures).expect("temp dir is creatable");
        std::fs::write(fixtures.join("broken.json"), b"{ not valid json at all")
            .expect("temp file is writable");

        let result = load_ground_truth(&root, "broken");
        std::fs::remove_dir_all(&root).ok();

        assert!(
            result.is_none(),
            "a malformed label must not yield fabricated ground truth"
        );
    }

    /// `load_ground_truth` falls through to `samples/private/<stem>.json` and
    /// projects the nested `PrivateSidecar` schema onto the flat
    /// `Extraction` the accuracy loop reads — field values map 1:1, and
    /// `mrz_checksums_valid` is `true` only when every recorded check passed.
    /// Uses a fabricated all-`X` document so no real PII enters the test.
    #[test]
    fn a_private_sidecar_projects_onto_extraction_via_load_ground_truth() {
        let root = std::env::temp_dir().join(format!(
            "synthpass-bench-private-sidecar-{}-{}",
            std::process::id(),
            fastrand_seed()
        ));
        let private = root.join("private");
        std::fs::create_dir_all(&private).expect("temp dir is creatable");
        std::fs::write(
            private.join("Country_ID_Private_Specimen_XX_XXX_2020_mrz.json"),
            br#"{
              "schema_version": 1,
              "document": { "kind": "id_card" },
              "fields": {
                "document_type": "ID", "issuing_country": "XXX",
                "document_number": "XX0000000", "surname": "XXXXX",
                "given_names": "XXXXX", "nationality": "XXX",
                "date_of_birth": "2000-01-01", "sex": "X",
                "date_of_expiry": "2030-01-01", "personal_number": null
              },
              "confidence": { "document_number": 0.9 },
              "provenance": { "kind": "human", "model": "n/a" },
              "mrz": {
                "lines": "IDXXX...\nLINE2...\nLINE3...",
                "format": "TD1",
                "checks": {
                  "document_number": true, "date_of_birth": true,
                  "date_of_expiry": true, "personal_number": true,
                  "composite": false
                }
              },
              "portrait": { "x": 0, "y": 0, "width": 1, "height": 1 },
              "extraction_method": "human"
            }"#,
        )
        .expect("temp file is writable");

        let e = load_ground_truth(&root, "Country_ID_Private_Specimen_XX_XXX_2020_mrz")
            .expect("private sidecar resolves through load_ground_truth");
        std::fs::remove_dir_all(&root).ok();

        assert_eq!(e.document_number.as_deref(), Some("XX0000000"));
        assert_eq!(e.date_of_birth.as_deref(), Some("2000-01-01"));
        assert_eq!(e.mrz_line.as_deref(), Some("IDXXX...\nLINE2...\nLINE3..."));
        assert_eq!(
            e.mrz_checksums_valid,
            Some(false),
            "one failing check (composite) must make the whole record checksum-invalid"
        );
        assert_eq!(e.extraction_method, "human");
    }

    /// Written to a temp tree rather than `samples/`, so this doesn't depend
    /// on any specific file surviving in the real (gitignored, local-mirror-
    /// only) bulk corpus — only `samples/ocr_fixtures/` is tracked, and nothing
    /// there is deliberately unlabelled.
    #[test]
    fn specimen_loader_reports_no_labels_when_absent() {
        let root = std::env::temp_dir().join(format!(
            "synthpass-bench-no-labels-{}-{}",
            std::process::id(),
            fastrand_seed()
        ));
        let samples = root.join("samples");
        std::fs::create_dir_all(samples.join("id_cards")).expect("temp dir is creatable");
        let image_path = samples.join("id_cards").join("unlabelled.png");
        image::DynamicImage::new_rgb8(2, 2)
            .save(&image_path)
            .expect("temp fixture writes");

        assert!(
            load_ground_truth(&samples, "unlabelled").is_none(),
            "no samples/ocr_fixtures/unlabelled.json should exist"
        );

        let specimen = load_specimen(&samples, &image_path, &MrzExpectations::default())
            .expect("the image itself exists and should decode");
        std::fs::remove_dir_all(&root).ok();

        assert_eq!(specimen.name, "unlabelled");
        assert!(
            specimen.labels.is_none(),
            "an unlabelled specimen must not silently acquire fabricated ground truth"
        );
    }

    /// A nonexistent image path is skipped gracefully — `None`, not a panic
    /// or an `Err` that would abort a whole-corpus load over one stale path.
    /// Same "one bad entry costs one entry" contract as `find_sample` in
    /// `crates/synthpass-ocr/examples/mrz_corpus.rs`.
    #[test]
    fn specimen_loader_handles_a_nonexistent_file_without_panicking() {
        let root = repo_root();
        let samples = root.join("samples");
        let bogus = samples.join("id_cards").join("does_not_exist_1234.png");
        assert!(load_specimen(&samples, &bogus, &MrzExpectations::default()).is_none());
    }

    /// The recursive walk finds specimens in more than one subdirectory,
    /// including `ocr_fixtures/` itself, and returns a deterministic
    /// (sorted) order rather than whatever order the OS filesystem API
    /// happens to yield.
    ///
    /// Deliberately exercises `find_image_files` + `load_ground_truth`
    /// directly rather than `load_real_specimens`, which also decodes every
    /// image with the `image` crate — real disk-and-CPU cost that belongs
    /// behind `--ignored`, not the default `cargo test` loop.
    ///
    /// Written to a temp tree rather than the real `samples/`: only
    /// `samples/ocr_fixtures/` is tracked in git, and every image there is
    /// hand-labelled by construction, so a fresh checkout with no local
    /// mirror of the gitignored bulk corpus has no unlabelled specimen at
    /// all — this test's "covers unlabelled" half must not depend on that.
    #[test]
    fn find_image_files_is_deterministic_and_covers_labelled_and_unlabelled_specimens() {
        let root = std::env::temp_dir().join(format!(
            "synthpass-bench-find-image-files-{}-{}",
            std::process::id(),
            fastrand_seed()
        ));
        let id_cards = root.join("id_cards");
        let ocr_fixtures = root.join("ocr_fixtures");
        std::fs::create_dir_all(&id_cards).expect("temp dir is creatable");
        std::fs::create_dir_all(&ocr_fixtures).expect("temp dir is creatable");

        image::DynamicImage::new_rgb8(2, 2)
            .save(id_cards.join("unlabelled.png"))
            .expect("temp fixture writes");
        image::DynamicImage::new_rgb8(2, 2)
            .save(ocr_fixtures.join("labelled.png"))
            .expect("temp fixture writes");
        std::fs::write(
            ocr_fixtures.join("labelled.json"),
            serde_json::to_vec(&synthpass_core::Extraction::default())
                .expect("Extraction serializes"),
        )
        .expect("temp fixture writes");

        let paths = find_image_files(&root, false);
        assert!(
            !paths.is_empty(),
            "the walk should find the images written to the temp tree"
        );

        let paths_again = find_image_files(&root, false);
        assert_eq!(
            paths, paths_again,
            "repeated walks of the same directory must yield the same order"
        );

        let has_label = |path: &Path| {
            path.file_stem()
                .and_then(|s| s.to_str())
                .is_some_and(|stem| load_ground_truth(&root, stem).is_some())
        };
        let has_labelled = paths.iter().any(|p| has_label(p));
        let has_unlabelled = paths.iter().any(|p| !has_label(p));
        std::fs::remove_dir_all(&root).ok();

        assert!(
            has_labelled,
            "ocr_fixtures/ should contribute at least one labelled specimen"
        );
        assert!(
            has_unlabelled,
            "an MRZ-less front like a bare ID-card face should have no label file"
        );
    }

    /// A `private`-tagged image must never enter the default walk, however
    /// deep it sits — this is the fix for the corpus silently growing
    /// 238 → 251 when real-PII specimens landed under `samples/private/`
    /// with no exclusion in place. Covers both signals independently: a file
    /// under a directory literally named `private` (the real local
    /// convention) with no token of its own, and a file carrying the corpus
    /// naming convention's `_Private_` token directly in its name.
    #[test]
    fn find_image_files_excludes_anything_tagged_private() {
        let root = std::env::temp_dir().join(format!(
            "synthpass-bench-exclude-private-{}-{}",
            std::process::id(),
            fastrand_seed()
        ));
        let passports = root.join("passports");
        let private_dir = root.join("private");
        std::fs::create_dir_all(&passports).expect("temp dir is creatable");
        std::fs::create_dir_all(&private_dir).expect("temp dir is creatable");

        image::DynamicImage::new_rgb8(2, 2)
            .save(passports.join("Public_Passport_Specimen_P0_XXX_2020_mrz.png"))
            .expect("temp fixture writes");
        image::DynamicImage::new_rgb8(2, 2)
            .save(passports.join("Country_Passport_Private_Specimen_P0_XXX_2020_mrz.png"))
            .expect("temp fixture writes");
        image::DynamicImage::new_rgb8(2, 2)
            .save(private_dir.join("unrelated_image_007.png"))
            .expect("temp fixture writes");

        let default_paths = find_image_files(&root, false);
        let with_private = find_image_files(&root, true);
        std::fs::remove_dir_all(&root).ok();

        assert_eq!(
            default_paths.len(),
            1,
            "default walk: only the one non-private file survives: {default_paths:?}"
        );
        assert!(
            default_paths[0]
                .file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.starts_with("Public_")),
            "the survivor must be the public specimen, not a private one: {default_paths:?}"
        );
        assert_eq!(
            with_private.len(),
            3,
            "include_private walk: every file is returned, private or not: {with_private:?}"
        );
    }

    /// The full, real end-to-end load — every image under `samples/`
    /// actually decoded via `load_real_specimens`, the way `provider-bench
    /// --real-specimens` uses it. Slow (~140 real photographs decoded), so
    /// it stays behind `--ignored` like this crate's other real-fixture
    /// tests (`some_clean_generated_documents_hit`); run with
    /// `cargo test -p synthpass-bench -- --ignored`.
    #[test]
    #[ignore]
    fn load_real_specimens_decodes_every_image_under_samples() {
        let root = repo_root();
        let specimens = load_real_specimens(&root.join("samples"), false);
        let expected = find_image_files(&root.join("samples"), false).len();
        assert_eq!(
            specimens.len(),
            expected,
            "every image `find_image_files` locates should decode successfully"
        );
        assert!(specimens.iter().any(|s| s.labels.is_some()));
        assert!(specimens.iter().any(|s| s.labels.is_none()));
    }

    fn repo_root() -> std::path::PathBuf {
        std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .ancestors()
            .nth(2)
            .expect("crates/synthpass-bench is two levels below the repo root")
            .to_path_buf()
    }
}
